contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function check(uint256 v) public {
        require(c.owner() == msg.sender, "caller must be owner");
        require(c.balanceOf(msg.sender) >= v, "insufficient balance");
        uint256 before = c.balanceOf(msg.sender);
        c.burn(v);
        assert(c.balanceOf(msg.sender) + v == before);
