contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function testBurn(uint256 v) public {
        // this contract is never the owner of c (owner is c's deployer)
        require(v == 0, "needs zero value for zero balance");
        bool reverted = false;
        // top-level state-changing call capturing revert behaviour
        assembly {
            let ptr := mload(0x40)
            mstore(ptr, 0x42966c6800000000000000000000000000000000000000000000000000000000)
            let ok := call(gas(), sload(c.slot), 0, ptr, 0x04, 0, 0)
            if iszero(ok) { reverted := true }
        }
        assert(reverted);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function invTest(address a, uint256 v) public {
        require(a != address(0));
        require(c.balanceOf(msg.sender) >= v);
        require(c.balanceOf(a) < v);
        c.transfer(a, v);
        assert(c.balanceOf(a) >= v);
    }
}
